/* ---------------------------------------------
   LOADER
--------------------------------------------- */
window.addEventListener("load", () => {
  const loader = document.getElementById("loader");
  setTimeout(() => loader.classList.add("is-hidden"), 350);
});

/* ---------------------------------------------
   NAV: scroll state + burger + mobile menu
--------------------------------------------- */
const nav = document.getElementById("nav");
const burgerBtn = document.getElementById("burgerBtn");
const mobileMenu = document.getElementById("mobileMenu");

function updateNavState() {
  nav.classList.toggle("is-scrolled", window.scrollY > 40);
}
updateNavState();
window.addEventListener("scroll", updateNavState, { passive: true });

function toggleMobileMenu(open) {
  const isOpen = open ?? !mobileMenu.classList.contains("is-open");
  mobileMenu.classList.toggle("is-open", isOpen);
  burgerBtn.setAttribute("aria-expanded", String(isOpen));
  document.body.style.overflow = isOpen ? "hidden" : "";
}
burgerBtn.addEventListener("click", () => toggleMobileMenu());
mobileMenu.querySelectorAll("a").forEach((a) => a.addEventListener("click", () => toggleMobileMenu(false)));

/* ---------------------------------------------
   SCROLL REVEAL
--------------------------------------------- */
const revealEls = document.querySelectorAll(".reveal");
const revealObserver = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add("is-visible");
        revealObserver.unobserve(entry.target);
      }
    });
  },
  { threshold: 0.15, rootMargin: "0px 0px -40px 0px" }
);
revealEls.forEach((el) => revealObserver.observe(el));

// Reveal hero content immediately (it's above the fold on load)
document.querySelectorAll(".hero .reveal").forEach((el) => {
  requestAnimationFrame(() => el.classList.add("is-visible"));
});

/* ---------------------------------------------
   ANIMATED COUNTERS
--------------------------------------------- */
function animateCounter(el) {
  const target = parseFloat(el.dataset.target);
  const isDecimal = target % 1 !== 0;
  const duration = 1400;
  const start = performance.now();

  function tick(now) {
    const progress = Math.min((now - start) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    const value = target * eased;
    el.textContent = isDecimal ? value.toFixed(1) : Math.round(value);
    if (progress < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}
const counterObserver = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        animateCounter(entry.target);
        counterObserver.unobserve(entry.target);
      }
    });
  },
  { threshold: 0.6 }
);
document.querySelectorAll("[data-counter]").forEach((el) => counterObserver.observe(el));

/* ---------------------------------------------
   BUILD MENU GRID + FILTERS
--------------------------------------------- */
const menuGrid = document.getElementById("menuGrid");

function renderMenu() {
  menuGrid.innerHTML = CONFIG.menuItems
    .map(
      (item, i) => `
      <article class="menu__card reveal" data-reveal data-category="${item.category}">
        <div class="menu__card-img"><img src="${item.img}" alt="${item.name}" loading="lazy"></div>
        <div class="menu__card-body">
          <span class="menu__card-tag">${item.tag}</span>
          <div class="menu__card-row">
            <span class="menu__card-name">${item.name}</span>
            <span class="menu__card-leader"></span>
            <span class="menu__card-price">${item.price}</span>
          </div>
          <p class="menu__card-desc">${item.desc}</p>
        </div>
      </article>`
    )
    .join("");

  // Observe newly created reveal elements
  menuGrid.querySelectorAll(".reveal").forEach((el) => revealObserver.observe(el));
}
renderMenu();

const menuFilters = document.querySelectorAll(".menu__filter");
menuFilters.forEach((btn) => {
  btn.addEventListener("click", () => {
    menuFilters.forEach((b) => b.classList.remove("is-active"));
    btn.classList.add("is-active");
    const filter = btn.dataset.filter;

    document.querySelectorAll(".menu__card").forEach((card) => {
      const match = filter === "all" || card.dataset.category === filter;
      card.classList.toggle("is-hidden", !match);
    });
  });
});

/* ---------------------------------------------
   BUILD GALLERY + LIGHTBOX
--------------------------------------------- */
const galleryGrid = document.getElementById("galleryGrid");

function renderGallery() {
  galleryGrid.innerHTML = CONFIG.galleryImages
    .map((item, i) => {
      const sizeClass = item.size === "wide" ? "gallery__item--wide" : item.size === "tall" ? "gallery__item--tall" : "";
      return `
      <div class="gallery__item ${sizeClass} reveal" data-reveal data-index="${i}">
        <img src="${item.img}" alt="${item.caption}" loading="lazy">
        <div class="gallery__item-overlay"><span>${item.caption}</span></div>
      </div>`;
    })
    .join("");

  galleryGrid.querySelectorAll(".reveal").forEach((el) => revealObserver.observe(el));
}
renderGallery();

const lightbox = document.getElementById("lightbox");
const lightboxImg = document.getElementById("lightboxImg");
const lightboxClose = document.getElementById("lightboxClose");
const lightboxPrev = document.getElementById("lightboxPrev");
const lightboxNext = document.getElementById("lightboxNext");
let currentImgIndex = 0;

function openLightbox(index) {
  currentImgIndex = index;
  lightboxImg.src = CONFIG.galleryImages[index].img;
  lightboxImg.alt = CONFIG.galleryImages[index].caption;
  lightbox.classList.add("is-open");
  document.body.style.overflow = "hidden";
}
function closeLightbox() {
  lightbox.classList.remove("is-open");
  document.body.style.overflow = "";
}
function showImg(delta) {
  currentImgIndex = (currentImgIndex + delta + CONFIG.galleryImages.length) % CONFIG.galleryImages.length;
  lightboxImg.src = CONFIG.galleryImages[currentImgIndex].img;
  lightboxImg.alt = CONFIG.galleryImages[currentImgIndex].caption;
}

galleryGrid.addEventListener("click", (e) => {
  const item = e.target.closest(".gallery__item");
  if (item) openLightbox(Number(item.dataset.index));
});
lightboxClose.addEventListener("click", closeLightbox);
lightboxPrev.addEventListener("click", () => showImg(-1));
lightboxNext.addEventListener("click", () => showImg(1));
lightbox.addEventListener("click", (e) => { if (e.target === lightbox) closeLightbox(); });
document.addEventListener("keydown", (e) => {
  if (!lightbox.classList.contains("is-open")) return;
  if (e.key === "Escape") closeLightbox();
  if (e.key === "ArrowLeft") showImg(-1);
  if (e.key === "ArrowRight") showImg(1);
});

/* ---------------------------------------------
   BUILD REVIEWS SLIDER
--------------------------------------------- */
const reviewsTrack = document.getElementById("reviewsTrack");
const reviewsDots = document.getElementById("reviewsDots");
let reviewIndex = 0;
let cardsPerView = 3;

function getCardsPerView() {
  if (window.innerWidth <= 680) return 1;
  if (window.innerWidth <= 1024) return 2;
  return 3;
}

function renderReviews() {
  reviewsTrack.innerHTML = CONFIG.reviews
    .map(
      (r) => `
      <article class="reviews__card">
        <span class="reviews__card-stars">★★★★★</span>
        <p class="reviews__quote">"${r.quote}"</p>
        <div class="reviews__card-name">${r.name}</div>
        <div class="reviews__card-tag">${r.tag}</div>
      </article>`
    )
    .join("");

  cardsPerView = getCardsPerView();
  const pages = Math.max(1, CONFIG.reviews.length - cardsPerView + 1);
  reviewsDots.innerHTML = Array.from({ length: pages })
    .map((_, i) => `<button aria-label="Go to review ${i + 1}" data-page="${i}"></button>`)
    .join("");
  updateReviewSlide();
}

function updateReviewSlide() {
  const cardWidth = reviewsTrack.children[0]?.getBoundingClientRect().width || 0;
  const gap = 24;
  reviewsTrack.style.transform = `translateX(-${reviewIndex * (cardWidth + gap)}px)`;
  reviewsDots.querySelectorAll("button").forEach((dot, i) => dot.classList.toggle("is-active", i === reviewIndex));
}

reviewsDots.addEventListener("click", (e) => {
  const btn = e.target.closest("button");
  if (!btn) return;
  reviewIndex = Number(btn.dataset.page);
  updateReviewSlide();
});

renderReviews();

let reviewResizeTimer;
window.addEventListener("resize", () => {
  clearTimeout(reviewResizeTimer);
  reviewResizeTimer = setTimeout(() => {
    const newCardsPerView = getCardsPerView();
    if (newCardsPerView !== cardsPerView) {
      reviewIndex = 0;
      renderReviews();
    } else {
      updateReviewSlide();
    }
  }, 200);
});

// Auto-advance reviews gently
let reviewAutoTimer = setInterval(() => {
  const maxIndex = reviewsDots.children.length - 1;
  reviewIndex = reviewIndex >= maxIndex ? 0 : reviewIndex + 1;
  updateReviewSlide();
}, 5000);
reviewsTrack.addEventListener("mouseenter", () => clearInterval(reviewAutoTimer));

/* ---------------------------------------------
   SCROLL TO TOP
--------------------------------------------- */
const scrollTopBtn = document.getElementById("scrollTop");
window.addEventListener(
  "scroll",
  () => {
    scrollTopBtn.classList.toggle("is-visible", window.scrollY > 600);
  },
  { passive: true }
);
scrollTopBtn.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "smooth" }));

